                 do_QueryInterface(m_copyState->m_srcSupport);
             if (srcFolder) {
-              copyService->NotifyCompletion(m_copyState->m_srcSupport, this,
+              nsIMsgFolder* arrived = m_copyState->m_arrFolder;
